css:
.concept-brief{--bri-ink:#172b36;--bri-muted:#536b77;--bri-accent:#31566a;--bri-accent-deep:#203f50;--bri-soft:#edf3f5;--bri-line:#d5e0e5;min-width:0;background:#f7f9f9;color:var(--bri-ink)}
.concept-brief .bri-wrap{width:min(1240px,calc(100% - 64px));margin-inline:auto}.concept-brief .bri-head{min-height:76px;display:flex;align-items:center;justify-content:space-between;gap:24px;border-bottom:1px solid var(--bri-line)}.concept-brief .bri-brand{min-height:44px;padding:7px 0;border:0;background:transparent;color:var(--bri-ink);font-size:20px;font-weight:800;letter-spacing:-.032em}.concept-brief .bri-nav{display:flex;align-items:center;gap:21px}.concept-brief .bri-nav button{position:relative;min-height:44px;padding:8px 2px;border:0;background:transparent;color:#526873;font-size:14px;font-weight:600}.concept-brief .bri-nav button::after{content:'';position:absolute;left:2px;right:2px;bottom:3px;height:2px;background:var(--bri-accent);transform:scaleX(0);transform-origin:center;transition:transform .18s cubic-bezier(.22,1,.36,1)}.concept-brief .bri-nav button[aria-current=page]{color:var(--bri-accent-deep);font-weight:800}.concept-brief .bri-nav button[aria-current=page]::after{transform:scaleX(1)}.concept-brief .bri-nav .bri-contact-link{min-width:92px;padding-inline:15px;border-radius:6px;background:var(--bri-accent);color:#fff}.concept-brief .bri-nav .bri-contact-link::after{display:none}.concept-brief .bri-nav .bri-contact-link[aria-current=page]{background:var(--bri-accent-deep);color:#fff}
.concept-brief .bri-home{padding:24px 0 20px}.concept-brief .bri-intro{display:flex;align-items:end;justify-content:space-between;gap:28px;margin-bottom:18px}.concept-brief .bri-intro h2{font-size:22px;font-weight:760;line-height:1.35;letter-spacing:-.025em}.concept-brief .bri-intro p{max-width:36em;color:var(--bri-muted);font-size:13px;line-height:1.65;text-align:right}.concept-brief .bri-stage{display:grid;grid-template-columns:minmax(0,1.54fr) minmax(340px,.82fr);min-height:512px;background:#fff;box-shadow:0 6px 8px rgba(23,43,54,.08)}.concept-brief .bri-figure{position:relative;min-width:0;min-height:512px;overflow:hidden;background:#203039;touch-action:pan-y;cursor:grab}.concept-brief .bri-figure.is-dragging{cursor:grabbing}.concept-brief .bri-photo{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:0;transform:scale(1.015) translateX(12px);transition:opacity .34s ease,transform .46s cubic-bezier(.22,1,.36,1);pointer-events:none;user-select:none;-webkit-user-drag:none}.concept-brief .bri-photo[data-bri-photo='0']{object-position:68% center}.concept-brief .bri-photo[data-bri-photo='1']{object-position:55% center}.concept-brief .bri-photo[data-bri-photo='2']{object-position:50% center}.concept-brief .bri-photo.is-active{opacity:1;transform:scale(1) translateX(0)}.concept-brief .bri-figure-shade{position:absolute;inset:58% 0 0;background:linear-gradient(180deg,transparent,rgba(12,27,35,.7));pointer-events:none}.concept-brief .bri-photo-meta{position:absolute;z-index:2;left:22px;right:22px;bottom:19px;display:flex;align-items:end;justify-content:space-between;gap:16px;color:#fff}.concept-brief .bri-photo-meta p{max-width:31em;font-size:13px;font-weight:720;line-height:1.45;text-shadow:0 1px 5px rgba(0,0,0,.45)}.concept-brief .bri-photo-meta span{flex:none;font-size:12px;font-variant-numeric:tabular-nums}.concept-brief .bri-drag-status{position:absolute!important;width:1px!important;height:1px!important;padding:0!important;margin:-1px!important;overflow:hidden!important;clip:rect(0,0,0,0)!important;white-space:nowrap!important;border:0!important}
.concept-brief .bri-copy{min-width:0;padding:38px 34px 30px;display:flex;flex-direction:column}.concept-brief .bri-kicker{margin-bottom:20px;color:#55717f;font-size:12px;font-weight:800}.concept-brief .bri-copy h1{max-width:10em;margin:0 0 18px;font-size:clamp(34px,3.05vw,46px);font-weight:780;line-height:1.2;letter-spacing:-.037em;text-wrap:balance}.concept-brief .bri-description{max-width:31em;min-height:104px;color:#4f6672;font-size:15px;line-height:1.78}.concept-brief .bri-copy.is-entering .bri-kicker,.concept-brief .bri-copy.is-entering h1,.concept-brief .bri-copy.is-entering .bri-description{animation:bri-copy-in .3s cubic-bezier(.22,1,.36,1)}.concept-brief .bri-copy.is-entering h1{animation-delay:.025s}.concept-brief .bri-copy.is-entering .bri-description{animation-delay:.05s}.concept-brief .bri-controls{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-top:auto;padding-top:24px}.concept-brief .bri-step-controls{display:flex;gap:7px}.concept-brief .bri-controls button,.concept-brief .bri-return{min-height:44px;padding:9px 13px;border:1px solid #91a5af;border-radius:5px;background:#fff;color:var(--bri-accent-deep);font-size:13px;font-weight:720;transition:background-color .16s ease,border-color .16s ease,color .16s ease,transform .16s ease}.concept-brief .bri-controls button:not(:disabled):hover,.concept-brief .bri-controls button:not(:disabled):focus-visible,.concept-brief .bri-return:hover,.concept-brief .bri-return:focus-visible{border-color:var(--bri-accent);background:var(--bri-soft)}.concept-brief .bri-controls button:not(:disabled):active,.concept-brief .bri-return:active{transform:translateY(1px)}.concept-brief .bri-controls button:disabled{border-color:#cfdadd;background:#f5f7f7;color:#97a7af;cursor:default}.concept-brief .bri-controls .bri-direct{border-color:var(--bri-accent);background:var(--bri-accent);color:#fff}.concept-brief .bri-controls .bri-direct:hover,.concept-brief .bri-controls .bri-direct:focus-visible{border