.concept-brief .bri-chapters{display:grid;grid-template-columns:repeat(3,1fr);background:#fff;border-top:1px solid var(--bri-line);border-bottom:1px solid var(--bri-line)}.concept-brief .bri-chapters button{position:relative;min-height:58px;padding:10px 14px;border:0;border-right:1px solid var(--bri-line);background:#fff;color:#647984;font-size:13px;font-weight:650}.concept-brief .bri-chapters button:last-child{border-right:0}.concept-brief .bri-chapters button::before{content:'';position:absolute;left:0;right:0;bottom:-1px;height:3px;background:var(--bri-accent);transform:scaleX(0);transition:transform .18s cubic-bezier(.22,1,.36,1)}.concept-brief .bri-chapters button[aria-pressed=true]{background:var(--bri-soft);color:var(--bri-accent-deep);font-weight:820}.concept-brief .bri-chapters button[aria-pressed=true]::before{transform:scaleX(1)}.concept-brief .bri-hint{padding-top:10px;color:#607681;font-size:11px;text-align:right}
.concept-brief .bri-contact{min-height:704px;padding:34px 0 38px;display:grid;grid-template-columns:minmax(290px,.72fr) minmax(430px,1.28fr);gap:38px;align-items:start}.concept-brief .bri-contact-copy{min-width:0}.concept-brief .bri-contact-copy h1{max-width:10em;margin:3px 0 16px;font-size:clamp(31px,3.2vw,42px);font-weight:780;line-height:1.24;letter-spacing:-.035em}.concept-brief .bri-contact-copy>p{max-width:31em;margin-bottom:20px;color:var(--bri-muted);font-size:14px;line-height:1.75}.concept-brief .bri-contact-scene{position:relative;height:245px;overflow:hidden;border-radius:8px}.concept-brief .bri-contact-scene img{width:100%;height:100%;object-fit:cover;object-position:57% center}.concept-brief .bri-contact-scene span{position:absolute;left:14px;bottom:12px;padding:5px 8px;border-radius:4px;background:rgba(20,39,49,.76);color:#fff;font-size:11px}.concept-brief .bri-return{margin-top:16px}.concept-brief [data-inline-form]{padding:24px;background:#fff;border:1px solid var(--bri-line);border-radius:10px}.concept-brief .inline-contact-form .cta{background:var(--bri-accent)}
.concept-brief .bri-footer{padding:20px 0;background:#e9eff1;border-top:1px solid #d3dfe4}.concept-brief .bri-footer .bri-wrap{display:grid;grid-template-columns:1fr 1.15fr;gap:30px;align-items:center}.concept-brief .bri-footer p{color:#536a76;font-size:11px;line-height:1.65}.concept-brief .bri-footer .restriction{color:#294554;font-size:12px}.concept-brief :is(button,a):focus-visible{outline-color:#176aa0}.concept-brief :is(button,a)[aria-current=page]:focus-visible{outline-offset:3px}
@keyframes bri-copy-in{from{opacity:.45;transform:translateX(9px)}to{opacity:1;transform:translateX(0)}}
@media(max-width:920px) and (min-width:761px){.concept-brief .bri-wrap{width:min(100% - 44px,1100px)}.concept-brief .bri-stage{grid-template-columns:minmax(0,1.24fr) minmax(315px,.76fr)}.concept-brief .bri-copy{padding:32px 27px 27px}.concept-brief .bri-copy h1{font-size:36px}.concept-brief .bri-description{font-size:14px}.concept-brief .bri-photo[data-bri-photo='0']{object-position:66% center}.concept-brief .bri-photo[data-bri-photo='1']{object-position:58% center}}
@media(max-width:760px){.concept-brief .bri-wrap{width:calc(100% - 30px)}.concept-brief .bri-head{min-height:108px;display:grid;grid-template-columns:1fr;align-content:center;gap:2px;padding-block:8px}.concept-brief .bri-brand{justify-self:start;font-size:17px}.concept-brief .bri-nav{width:100%;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:3px}.concept-brief .bri-nav button,.concept-brief .bri-nav .bri-contact-link{display:flex;align-items:center;justify-content:center;min-width:0;min-height:44px;padding:6px 3px;border-radius:4px;font-size:10.5px;line-height:1.2;white-space:nowrap}.concept-brief .bri-nav button::after{left:4px;right:4px;bottom:1px}.concept-brief .bri-home{padding:15px 0 14px}.concept-brief .bri-intro{display:block;margin-bottom:12px}.concept-brief .bri-intro h2{font-size:18px}.concept-brief .bri-intro p{margin-top:4px;font-size:11.5px;line-height:1.55;text-align:left}.concept-brief .bri-intro p br{display:none}.concept-brief .bri-stage{display:flex;flex-direction:column;min-height:0;box-shadow:0 4px 7px rgba(23,43,54,.07)}.concept-brief .bri-figure{flex:none;min-height:0;height:clamp(220px,61vw,250px)}.concept-brief .bri-photo[data-bri-photo='0']{object-position:67% center}.concept-brief .bri-photo[data-bri-photo='1']{object-position:52% center}.concept-brief .bri-photo[data-bri-photo='2']{object-position:49% center}.concept-brief .bri-photo-meta{left:12px;right:12px;bottom:10px;gap:10px}.concept-brief .bri-photo-meta p{font-size:11px}.concept-brief .bri-photo-meta span{font-size:10px}.concept-brief .bri-copy{min-height:276px;padding:19px 17px 17px}.concept-brief .bri-kicker{margin-bottom:8px;font-size:10.5px}.concept-brief .bri-copy h1{max-width:none;margin-bottom:10px;font-size:clamp(27px,8.1vw,31px);line-height:1.18;letter-spacing:-.035em}.concept-brief .bri-description{min-height:68px;font-size:12.5px;line-height:1.62}.concept-brief .bri-controls{padding-top:15px;gap:7px}.concept-brief .bri-step-controls{gap:5px}.concept-brief .bri-controls button{min-height:44px;padding:7px 9px;font-size:11.5px}.concept-brief .bri-controls .bri-direct{padding-inline:12px}.concept-brief .bri-chapters button{min-height:50px;padding:7px 5px;font-size:11.5px}.concept-brief .bri-hint{padding-top:7px;font-size:10px;text-align:left}.concept-brief .bri-footer{padding:15px 0}.concept-brief .bri-footer .bri-wrap{grid-template-columns:1fr;gap:7px}.concept-brief .bri-footer p{font-size:10.5px}.concept-brief .bri-footer .restriction{font-size:10.5px}.concept-brief .bri-contact{min-height:0;padding:22px 0 26px;grid-template-columns:1fr;gap:18px}.concept-brief .bri-contact-copy h1{max-width:none;margin-bottom:10px;font-size:28px}.concept-brief .bri-contact-copy>p{margin-bottom:0;font-size:12.5px}.concept-brief .bri-contact-scene{display:none}.concept-brief .bri-return{margin-top:12px;font-size:12px}.concept-brief [data-inline-form]{padding:17px 15px;border-radius:8px}}
@media(max-width:370px){.concept-brief .bri-wrap{width:calc(100% - 24px)}.concept-brief .bri-brand{font-size:16px}.concept-brief .bri-nav button,.concept-brief .bri-nav .bri-contact-link{font-size:10px}.concept-brief .bri-home{padding-top:12px}.concept-brief .bri-figure{height:218px}.concept-brief .bri-copy{min-height:272px;padding-inline:15px}.concept-brief .bri-copy h1{font-size:27px}.concept-brief .bri-controls button{padding-inline:7px;font-size:11px}.concept-brief .bri-chapters button{font-size:11px}}
@media(prefers-reduced-motion:reduce){.concept-brief *,.concept-brief *::before,.concept-brief *::after{animation-duration:.01ms!important;animation-delay:0ms!important;transition-duration:.01ms!important;scroll-behavior:auto!important}}
